// Specialized TEV pixel shaders at run time (gx_spec.cpp): a shader per TEV
// configuration, generated by gx_tevgen.cpp, compiled on a worker thread and
// cached; draws whose shader is not ready yet use the ubershader.
//
// FORECAST_SPECIALIZED: 0 always draws with the ubershader; 1 (default where
// a compiler is available: Metal always, Windows when the SDK's
// dxcompiler.dll is found) specializes. Testing values: "sync" compiles each
// new shader on the spot, so every draw is specialized (slow; for comparing
// frames), "worker" / "main" choose where the SDL shader objects are created
// (default: the worker on Apple, where creating one compiles the MSL; the
// main thread elsewhere). FORECAST_SPECIALIZED_DUMP=dir writes each
// generated shader (HLSL and MSL) and its key to dir.
#ifndef GX_SPEC_H
#define GX_SPEC_H

#include <types.h>

struct SDL_GPUDevice;
struct SDL_GPUShader;
struct GXTevUniforms;

void gx_spec_init(SDL_GPUDevice* dev);
bool gx_spec_enabled(void);

// The specialized shader for a draw's TEV state (u, with texBound set):
// returns its id (> 0) and sets *shader once it is ready (else NULL; the
// draw uses the ubershader). Returns 0 when specialization is off.
u32 gx_spec_lookup(const GXTevUniforms& u, SDL_GPUShader** shader);

// Main-thread budget for creating SDL shader and pipeline objects: a few
// milliseconds a frame (unlimited in sync mode). Callers check before and
// charge after creating one.
bool gx_spec_budget_left(void);
void gx_spec_budget_charge(u64 ns);

// A pipeline for shader id with pipeline key bits now exists: remembered in
// the data folder, so the next start creates it ahead of time.
void gx_spec_pipeline_created(u32 id, u32 pipeBits);

// Statistics: a draw that wants shader id was recorded with it (or, not
// ready yet, with the ubershader).
void gx_spec_count_draw(u32 id, bool specialized);

// Once a frame (after submitting): takes finished compiles, creates their SDL
// objects within the budget, pre-creates remembered pipelines through
// make_pipe (returns false when out of budget), logs a summary every 600
// frames, and with logFrame the shaders this frame used.
typedef bool (*GXSpecMakePipe)(u32 id, SDL_GPUShader* shader, u32 pipeBits);
void gx_spec_frame_end(u32 frame, GXSpecMakePipe make_pipe, bool logFrame);

#endif
